      tex: 512, facadePx: 512, shopPx: 1024, neonPx: 1024,
      atlasCols: 8, atlasRows: 4,
      godray: true, skyline: true, screens: 4,
      ambientDust: 320, dustPool: 620, fogDensity: 46e-4,
      wires: 140, rebar: 62, rails: 96, cars: 14, decals: 30,
