      ctx2.strokeStyle = "rgba(150,104,96,0.26)";
      ctx2.lineWidth = Math.max(1, s * 0.02);
      ctx2.beginPath();
      ctx2.moveTo(s * 0.525, s * 0.47);
      ctx2.quadraticCurveTo(s * 0.545, s * 0.55, s * 0.525, s * 0.6);
      ctx2.stroke();
      ctx2.fillStyle = "rgba(140,92,86,0.24)";
